-- PT114-S2-Q11. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT114-S2-Q11$batch04$ AND q.stimulus=$batch04$Human intelligence is not possible without human emotions. A computer is something that can never have emotions, so for that reason alone a computer will never be able to display intelligence.$batch04$ AND q.prompt=$batch04$Which one of the following is an assumption on which the argument depends?$batch04$ AND q.correct_choice=$batch04$E$batch04$) THEN RAISE EXCEPTION 'Question changed: PT114-S2-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT114-S2-Q11$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S2-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT114-S2-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$A computer will never be able to display intelligence.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$Human intelligence is impossible without human emotions. A computer can never have emotions.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The evidence is about *human* intelligence. The conclusion is about intelligence of any kind. A computer could have some other kind of intelligence that does not need emotions. The argument needs emotions to be required for all intelligence.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A link: any intelligence requires the capacity to have emotions.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT114-S2-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$This says emotions require intelligence. The argument needs the reverse: intelligence requires emotions.$batch04$), ($batch04$B$batch04$, $batch04$The argument says computers can *never* have emotions, so how far technology advances does not matter.$batch04$), ($batch04$C$batch04$, $batch04$Identifying one's emotions is a new and stronger requirement than having them.$batch04$), ($batch04$D$batch04$, $batch04$The argument is about whether a computer has any intelligence at all, not how much.$batch04$), ($batch04$E$batch04$, $batch04$Negate it: something can be intelligent *without* the capacity for emotions. Then a computer could be intelligent despite having no emotions, and the conclusion falls apart.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT114-S2-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
